/* HEXA BATTLEGROUNDS setup — PART 61 OF 84. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-bomb-6', 'bomb', 'mission', 'Bomb Defusal', 'game', 1, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Green, Black, White, Green, Red.\nSerial number: TN16A5.  LED: GREEN.","game":{"type":"bomb","wires":["green","black","white","green","red"],"serial":"TN16A5","led":"green"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If the serial number contains the digit 7, cut the THIRD wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["5"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'green,black,white,green,red · TN16A5 · green → LED green → last wire → wire 5', null, 25, 'published'), ('mission-bomb-7', 'bomb', 'mission', 'Bomb Defusal', 'game', 1, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Green, White, Blue, Black, Yellow.\nSerial number: HX17Z4.  LED: RED.","game":{"type":"bomb","wires":["green","white","blue","black","yellow"],"serial":"HX17Z4","led":"red"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there are exactly two BLACK wires, cut the FIRST black wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["1"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'green,white,blue,black,yellow · HX17Z4 · red → otherwise → first wire → wire 1', null, 25, 'published'), ('mission-bomb-8', 'bomb', 'mission', 'Bomb Defusal', 'game', 2, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Black, Yellow, Yellow, Green.\nSerial number: OM87Z5.  LED: BLUE.","game":{"type":"bomb","wires":["black","yellow","yellow","green"],"serial":"OM87Z5","led":"blue"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If the LED is BLUE and the first wire is YELLOW, cut the LAST wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["1"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'black,yellow,yellow,green · OM87Z5 · blue → otherwise → first wire → wire 1', null, 25, 'published'), ('mission-bomb-9', 'bomb', 'mission', 'Bomb Defusal', 'game', 1, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Black, Yellow, Green, Blue.\nSerial number: OM90Q2.  LED: GREEN.","game":{"type":"bomb","wires":["black","yellow","green","blue"],"serial":"OM90Q2","led":"green"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there are no RED wires at all, cut the wire just ABOVE the last one — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["3"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'black,yellow,green,blue · OM90Q2 · green → override: If there are no RED wires at all, cut the wire just ABOVE the last one — ignore the manual. → wire 3', null, 25, 'published'), ('mission-bomb-10', 'bomb', 'mission', 'Bomb Defusal', 'game', 1, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Blue, Yellow, White, Black.\nSerial number: SR17Z0.  LED: RED.","game":{"type":"bomb","wires":["blue","yellow","white","black"],"serial":"SR17Z0","led":"red"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there is a WHITE wire and the LED is RED, cut the white wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["3"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'blue,yellow,white,black · SR17Z0 · red → override: If there is a WHITE wire and the LED is RED, cut the white wire — ignore the manual. → wire 3', null, 25, 'published'), ('mission-bomb-11', 'bomb', 'mission', 'Bomb Defusal', 'game', 2, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Yellow, White, White, Blue.\nSerial number: SR89Q2.  LED: RED.","game":{"type":"bomb","wires":["yellow","white","white","blue"],"serial":"SR89Q2","led":"red"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If the serial number contains the digit 7, cut the THIRD wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["1"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'yellow,white,white,blue · SR89Q2 · red → otherwise → first wire → wire 1', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();
